  const card = document.querySelector('main > div');
  function walk(el, depth) {
    let out = '';
    for (const c of el.children) {
      out += '  '.repeat(depth) + c.tagName + ' | ' + c.className + '\n';
      out += walk(c, depth+1);
    }
    return out;
  }
  // find the pricing card (first section-like div in main)
  const main = document.querySelector('main');
  return walk(main, 0);
}

