() => {
  let found = [];
  for (const sheet of document.styleSheets) {
    let rules;
    try { rules = sheet.cssRules; } catch(e) { continue; }
    for (const rule of rules) {
      if (rule.cssText && /aspect/.test(rule.cssText)) found.push(rule.cssText);
    }
  }
  return {aspectRules: found.slice(0,10), sheets: document.styleSheets.length};
}

